// AllProtectedDirs returns the union of ProtectedDirs from all registered agents.
func AllProtectedDirs() []string {
	// Copy factories under the lock, then release before calling external code.
	registryMu.RLock()
	factories := make([]Factory, 0, len(registry))
	for _, f := range registry {
		factories = append(factories, f)
	}
	registryMu.RUnlock()

	seen := make(map[string]struct{})
	var dirs []string
	for _, factory := range factories {
		for _, d := range factory().ProtectedDirs() {
			if _, ok := seen[d]; !ok {
				seen[d] = struct{}{}
				dirs = append(dirs, d)
			}
		}
	}
	slices.Sort(dirs)
	return dirs
}

// AllHookConfigRelPaths returns the worktree-relative path of every registered
// agent's hook-configuration file, for the agents that declare one
// (HookConfigLocator). Sorted and deduplicated.
func AllHookConfigRelPaths() []string {
	registryMu.RLock()
	factories := make([]Factory, 0, len(registry))
	for _, f := range registry {
		factories = append(factories, f)
	}
	registryMu.RUnlock()

	seen := make(map[string]struct{})
	var out []string
	for _, factory := range factories {
		locator, ok := factory().(HookConfigLocator)
		if !ok {
			continue
		}
		p := locator.HookConfigRelPath()
		if p == "" {
			continue
		}
		if _, dup := seen[p]; dup {
			continue
		}
		seen[p] = struct{}{}
		out = append(out, p)
	}
	slices.Sort(out)
	return out
}

