func TestWorktreeFileName_FollowsAnAbsoluteInRepoLink(t *testing.T) {
	t.Parallel()

	if runtime.GOOS == "windows" {
		t.Skip("symlink creation needs elevation on Windows")
	}

	dir := t.TempDir()
	shared := filepath.Join(dir, "shared")
	require.NoError(t, os.MkdirAll(shared, 0o755))
	target := filepath.Join(shared, "vercel.json")
	require.NoError(t, os.WriteFile(target, []byte("{}"), 0o644))
	require.NoError(t, os.Symlink(target, filepath.Join(dir, "vercel.json")))

	root, err := os.OpenRoot(dir)
	require.NoError(t, err)
	defer root.Close()

	name, found, err := worktreeFileName(dir, root, "vercel.json")
	require.NoError(t, err)
	require.True(t, found, "an absolute link resolving inside the worktree must be found")
	require.Equal(t, "shared/vercel.json", name, "the resolved name is what the read goes through")
}

// A link leaving the worktree stays refused — that is the property the anchor is
