	t.Parallel()

	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("héllo"), 0o644); err != nil {
		t.Fatal(err)
	}

	got, ok := readCapped(dir, "README.md", 100)
	if !ok {
		t.Fatal("readCapped() not ok")
	}
	if got != "héllo" {
		t.Errorf("readCapped() = %q, want héllo", got)
	}
}

